scriptdefs
= RustboroCity_DevonCorp_3F_EventScript_MeetPresident
lockall
msgbox	Dies ist der dritte Stock der DEVON CORPORATION.Auf diesem Stockwerk liegt das BÜRO unseres PRÄSIDENTEN.Wie auch immer, ich kann dir gar nicht sagen, wie dankbar ich für das bin, was du getan hast.Ähm… Übrigens, dieses Paket, das du für uns zurückgeholt hast…Könntest du das zur WERFT in SLATEPORT liefern?Es wäre furchtbar, wenn diese Räuber versuchen würden, es sich noch einmal zu holen.Äh… Hehehe, also, könnte ich mich darauf verlassen, dass du das für mich erledigst?Ach, richtig. Könntest du hier kurz warten?
closemessage
applymovement LOCALID_DEVON_CORP_3F_EMPLOYEE RustboroCity_DevonCorp_3F_Movement_EmployeeWalkOffscreen
waitmovement 0
delay 80
applymovement LOCALID_DEVON_CORP_3F_EMPLOYEE RustboroCity_DevonCorp_3F_Movement_EmployeeReturnToPlayer
waitmovement 0
msgbox	Unser PRÄSIDENT möchte gerne mit dir sprechen.Bitte komm mit mir.
closemessage
playbgm MUS_FOLLOW_ME FALSE
applymovement LOCALID_DEVON_CORP_3F_EMPLOYEE RustboroCity_DevonCorp_3F_Movement_LeadPlayerToPresident
applymovement LOCALID_PLAYER RustboroCity_DevonCorp_3F_Movement_PlayerFollowToPresident
waitmovement 0
msgbox	Bitte, geh vor.
closemessage
fadedefaultbgm
applymovement LOCALID_DEVON_CORP_3F_EMPLOYEE RustboroCity_DevonCorp_3F_Movement_EmployeeFaceDesk
applymovement LOCALID_PLAYER RustboroCity_DevonCorp_3F_Movement_PlayerApproachDesk
waitmovement 0
msgbox	Ich bin MR. STONE, der PRÄSIDENT der DEVON CORPORATION.Ich habe gerade von dir gehört!Du hast unsere Mitarbeiter nicht nur einmal, sondern gleich zweimal gerettet!Ich habe eine Bitte an eine so großartige Person wie dich.Wie ich höre, lieferst du gerade ein Paket zur WERFT in SLATEPORT.Nun, könntest du auf dem Weg in DEWFORD TOWN vorbeischauen?Ich hätte gerne, dass du einen BRIEF an STEVEN in DEWFORD überbringst.
giveitem ITEM_LETTER
msgbox	MR. STONE: Nun, du solltest wissen, dass ich ein großartiger PRÄSIDENT bin.Ich wäre also niemals so geizig, um eine Gefälligkeit ohne Gegenleistung zu erbitten.Deshalb möchte ich, dass du das hier bekommst!
playfanfare MUS_OBTAIN_ITEM
msgbox	PLAYER erhielt einen POKéNAV.
waitfanfare
setflag FLAG_SYS_POKENAV_GET
setflag FLAG_RECEIVED_POKENAV
setflag FLAG_HIDE_RUSTBORO_CITY_POKEMON_SCHOOL_SCOTT
msgbox	MR. STONE: Dieses Gerät…Es ist ein POKéMON-NAVIGATOR, kurz POKéNAV.Es ist ein unverzichtbares Werkzeug für jeden TRAINER auf Abenteuer.Es enthält eine Karte der HOENN-Region.Du kannst die Standorte von DEWFORD und SLATEPORT ganz einfach nachschlagen!Übrigens habe ich gehört, dass finstere Verbrecher--MAGMA und AQUA, glaube ich-- weit und breit Unruhe stiften.Ich denke, es wäre am besten, wenn du dich erst ausruhst, bevor du dich auf den Weg machst.
closemessage
call Common_EventScript_OutOfCenterPartyHeal
msgbox	MR. STONE: Nun denn, PLAYER, sei vorsichtig und pass gut auf dich auf!
setflag FLAG_HIDE_ROUTE_116_WANDAS_BOYFRIEND
clearflag FLAG_HIDE_RUSTURF_TUNNEL_WANDAS_BOYFRIEND
clearflag FLAG_HIDE_RUSTURF_TUNNEL_WANDA
clearflag FLAG_HIDE_BRINEYS_HOUSE_MR_BRINEY
clearflag FLAG_HIDE_BRINEYS_HOUSE_PEEKO
setvar VAR_BRINEY_LOCATION 1
clearflag FLAG_HIDE_RUSTBORO_CITY_RIVAL
setvar VAR_DEVON_CORP_3F_STATE 1
setvar VAR_RUSTBORO_CITY_STATE 6
releaseall
end
= RustboroCity_DevonCorp_3F_EventScript_MrStone
lock
faceplayer
goto_if_set FLAG_RECEIVED_EXP_SHARE RustboroCity_DevonCorp_3F_EventScript_MrStoneAfterFavor
goto_if_set FLAG_DELIVERED_STEVEN_LETTER RustboroCity_DevonCorp_3F_EventScript_GiveExpShare
msgbox	MR. STONE: Ich verlasse mich auf dich!
closemessage
applymovement VAR_LAST_TALKED Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= RustboroCity_DevonCorp_3F_EventScript_GiveExpShare
msgbox	MR. STONE: Du hast meinen BRIEF überbracht? Herzlichen Dank!So möchte ich mich bei dir bedanken. Es sollte dir als TRAINER helfen.
giveitem ITEM_EXP_SHARE
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_EXP_SHARE
msgbox	MR. STONE: Ein POKéMON, das den EXP.-TEILER trägt, erhält einen Teil der EXP-Punkte aus dem Kampf.Es bekommt EXP-Punkte, auch wenn es gar nicht mitgekämpft hat.Ich würde sagen, der EXP.-TEILER ist ziemlich nützlich, um schwache POKéMON aufzuziehen.
closemessage
applymovement VAR_LAST_TALKED Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= RustboroCity_DevonCorp_3F_EventScript_MrStoneAfterFavor
msgbox	MR. STONE: Seit meiner Jugend habe ich mich ganz in die Arbeit vertieft.Deshalb kenne ich mich mit Trends und solchen Dingen nicht aus.Aber wollen wirklich alle jungen Leute TRAINER in der POKéMON-LIGA werden?
closemessage
applymovement VAR_LAST_TALKED Common_Movement_FaceOriginalDirection
waitmovement 0
release
end
= RustboroCity_DevonCorp_3F_EventScript_Employee
lock
faceplayer
goto_if_set FLAG_RECEIVED_REPEAT_BALL RustboroCity_DevonCorp_3F_EventScript_EmployeeBalls
msgbox	Wenn du die WERFT in SLATEPORT besuchst, solltest du zu CAPT. STERN gehen.
release
end
= RustboroCity_DevonCorp_3F_EventScript_EmployeeBalls
msgbox	DEVONs neue Produkte, der REPEAT BALL und der TIMER BALL, sind bei TRAINERN riesig beliebt geworden.
release
end
